import 'package:flutter_drawing_board/flutter_drawing_board.dart';

final controller = DrawingController();

Widget build(BuildContext context) {
  return Scaffold(
    body: Column(
      children: [
        Expanded(child: DrawingBoard(controller: controller, background: Container(color: Colors.white))),
        DrawingBar(controller: controller, tools: [DefaultActionItem.undo(), DefaultActionItem.redo(), DefaultActionItem.clear()]),
        DrawingBar(controller: controller, tools: [DefaultToolItem.pen(), DefaultToolItem.brush(), DefaultToolItem.rectangle()]),
      ],
    ),
  );
}
